def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]

    # Find the aligned pair that forms the main line.
    candidates = []
    for r in range(h):
        cols = [c for rr, c in points if rr == r]
        if len(cols) >= 2:
            candidates.append((max(cols) - min(cols), "row", r, min(cols), max(cols)))
    for c in range(w):
        rows = [r for r, cc in points if cc == c]
        if len(rows) >= 2:
            candidates.append((max(rows) - min(rows), "col", c, min(rows), max(rows)))

    out = [row[:] for row in grid]
    if not candidates:
        return out

    _, axis, fixed, lo, hi = max(candidates)
    if axis == "row":
        for c in range(lo, hi + 1):
            if out[fixed][c] == 0:
                out[fixed][c] = 3
        for r, c in points:
            if r != fixed:
                step = 1 if fixed > r else -1
                for rr in range(r + step, fixed, step):
                    if out[rr][c] == 0:
                        out[rr][c] = 3
    else:
        for r in range(lo, hi + 1):
            if out[r][fixed] == 0:
                out[r][fixed] = 3
        for r, c in points:
            if c != fixed:
                step = 1 if fixed > c else -1
                for cc in range(c + step, fixed, step):
                    if out[r][cc] == 0:
                        out[r][cc] = 3
    return out
